"""Reading log lines: `IP TIMESTAMP METHOD PATH STATUS`."""
from collections import namedtuple

Request = namedtuple("Request", "ip when method path status")


def parse_line(line):
    """Return a Request, or raise ValueError for a malformed line."""
    parts = line.split()
    if len(parts) != 5 or not parts[4].isdigit():
        raise ValueError("malformed line")
    return Request(parts[0], parts[1], parts[2], parts[3], int(parts[4]))


def parse_file(path):
    """Return (requests, numbers of the malformed lines)."""
    requests, skipped = [], []
    with open(path, encoding="utf-8") as handle:
        for number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            try:
                requests.append(parse_line(line))
            except ValueError:
                skipped.append(number)
    return requests, skipped

