"""Counting requests."""
from collections import Counter


def top_paths(requests, limit):
    """Return the `limit` most requested (path, count) pairs."""
    return Counter(r.path for r in requests).most_common(limit)


def status_counts(requests):
    """Return {status: count}."""
    return dict(Counter(r.status for r in requests))

