import unittest

from digest.parse import parse_line


class ParseLineTests(unittest.TestCase):
    def test_reads_five_fields(self):
        request = parse_line("10.0.0.1 2026-05-01T10:15:00 GET /home 200")
        self.assertEqual((request.path, request.status), ("/home", 200))

    def test_short_line_is_malformed(self):
        with self.assertRaises(ValueError):
            parse_line("10.0.0.1 GET")


if __name__ == "__main__":
    unittest.main()

