import unittest

from digest.parse import parse_line
from digest.stats import status_counts, top_paths

LINES = ["1.1.1.1 t GET /a 200", "1.1.1.2 t GET /a 200", "1.1.1.3 t GET /b 500"]


class StatsTests(unittest.TestCase):
    def setUp(self):
        self.requests = [parse_line(line) for line in LINES]

    def test_top_path_comes_first(self):
        self.assertEqual(top_paths(self.requests, 1), [("/a", 2)])

    def test_status_counts(self):
        self.assertEqual(status_counts(self.requests), {200: 2, 500: 1})


if __name__ == "__main__":
    unittest.main()
